select 'public.officer_new_roster' as relation,count(*) as row_count,coalesce(jsonb_agg(jsonb_build_object('id',t.id,'student_id',t.student_id,'organization_id',t.organization_id,'election_id',t.election_id,'candidate_id',t.candidate_id,'position_id',t.position_id,'selection_type',t.selection_type,'leadership_academic_year',t.leadership_academic_year,'created_at',t.created_at,'row_sha256',encode(sha256(convert_to(to_jsonb(t)::text,'UTF8')),'hex')) order by to_jsonb(t)->>'id',to_jsonb(t)->>'student_id'),'[]') as records from public.officer_new_roster t where t.election_id in(select id from target_elections) or t.position_id in(select id from target_positions) or t.candidate_id in(select id from target_candidates)
union all
select 'public.officer_leadership_releases' as relation,count(*) as row_count,coalesce(jsonb_agg(jsonb_build_object('id',t.id,'organization_id',t.organization_id,'election_id',t.election_id,'academic_term_id',t.academic_term_id,'elected_count',t.elected_count,'appointed_count',t.appointed_count,'released_at',t.released_at,'term_label',t.term_label,'leadership_academic_year',t.leadership_academic_year,'row_sha256',encode(sha256(convert_to(to_jsonb(t)::text,'UTF8')),'hex')) order by to_jsonb(t)->>'id',to_jsonb(t)->>'student_id'),'[]') as records from public.officer_leadership_releases t where t.academic_term_id=2 or t.election_id in(select id from target_elections)
union all
select 'public.election_campaign_snapshots' as relation,count(*) as row_count,coalesce(jsonb_agg(jsonb_build_object('id',t.id,'election_id',t.election_id,'organization_id',t.organization_id,'capture_kind',t.capture_kind,'content_hash',t.content_hash,'captured_at',t.captured_at,'row_sha256',encode(sha256(convert_to(to_jsonb(t)::text,'UTF8')),'hex')) order by to_jsonb(t)->>'id',to_jsonb(t)->>'student_id'),'[]') as records from public.election_campaign_snapshots t where t.election_id in(select id from target_elections)
union all
select 'public.election_officer_publications' as relation,count(*) as row_count,coalesce(jsonb_agg(jsonb_build_object('id',t.id,'election_id',t.election_id,'organization_id',t.organization_id,'campaign_snapshot_id',t.campaign_snapshot_id,'published_at',t.published_at,'content_hash',t.content_hash,'row_sha256',encode(sha256(convert_to(to_jsonb(t)::text,'UTF8')),'hex')) order by to_jsonb(t)->>'id',to_jsonb(t)->>'student_id'),'[]') as records from public.election_officer_publications t where t.election_id in(select id from target_elections) or t.campaign_snapshot_id in(select id from target_snapshots)
union all
select 'public.election_officer_publication_entries' as relation,count(*) as row_count,coalesce(jsonb_agg(jsonb_build_object('id',t.id,'publication_id',t.publication_id,'source_officer_id',t.source_officer_id,'selection_type',t.selection_type,'term_label',t.term_label,'row_sha256',encode(sha256(convert_to(to_jsonb(t)::text,'UTF8')),'hex')) order by to_jsonb(t)->>'id',to_jsonb(t)->>'student_id'),'[]') as records from public.election_officer_publication_entries t where t.publication_id in(select id from target_publications) or t.source_officer_id in(select id from target_officers)
union all
select 'public.archived_elections' as relation,count(*) as row_count,coalesce(jsonb_agg(jsonb_build_object('id',t.id,'election_id',t.election_id,'organization_id',t.organization_id,'title',t.title,'archived_at',t.archived_at,'total_votes',t.total_votes,'total_voters',t.total_voters,'row_sha256',encode(sha256(convert_to(to_jsonb(t)::text,'UTF8')),'hex')) order by to_jsonb(t)->>'id',to_jsonb(t)->>'student_id'),'[]') as records from public.archived_elections t where t.election_id in(select id from target_elections) or t.snapshot @? '$.**.academic_term_id ? (@ == 2 || @ == "2")'
union all
select 'public.eligibility_rules' as relation,count(*) as row_count,coalesce(jsonb_agg(jsonb_build_object('id',t.id,'election_id',t.election_id,'program',t.program,'min_year_level',t.min_year_level,'max_year_level',t.max_year_level,'row_sha256',encode(sha256(convert_to(to_jsonb(t)::text,'UTF8')),'hex')) order by to_jsonb(t)->>'id',to_jsonb(t)->>'student_id'),'[]') as records from public.eligibility_rules t where t.election_id in(select id from target_elections)
union all
select 'public.masterlist_imports' as relation,count(*) as row_count,coalesce(jsonb_agg(jsonb_build_object('id',t.id,'academic_term_id',t.academic_term_id,'file_name',t.file_name,'import_status',t.import_status,'import_scope',t.import_scope,'total_rows',t.total_rows,'valid_rows',t.valid_rows,'invalid_rows',t.invalid_rows,'conflict_rows',t.conflict_rows,'created_at',t.created_at,'finalized_at',t.finalized_at,'row_sha256',encode(sha256(convert_to(to_jsonb(t)::text,'UTF8')),'hex')) order by to_jsonb(t)->>'id',to_jsonb(t)->>'student_id'),'[]') as records from public.masterlist_imports t where t.academic_term_id=2
union all
select 'public.masterlist_import_rows' as relation,count(*) as row_count,coalesce(jsonb_agg(jsonb_build_object('id',t.id,'import_id',t.import_id,'row_number',t.row_number,'matched_student_id',t.matched_student_id,'reconciliation_status',t.reconciliation_status,'review_status',t.review_status,'review_decision',t.review_decision,'created_at',t.created_at,'reviewed_at',t.reviewed_at,'row_sha256',encode(sha256(convert_to(to_jsonb(t)::text,'UTF8')),'hex')) order by to_jsonb(t)->>'id',to_jsonb(t)->>'student_id'),'[]') as records from public.masterlist_import_rows t where t.import_id in(select id from target_imports)
union all
select 'public.student_term_enrollments' as relation,count(*) as row_count,coalesce(jsonb_agg(jsonb_build_object('id',t.id,'student_id',t.student_id,'academic_term_id',t.academic_term_id,'enrollment_status',t.enrollment_status,'source',t.source,'program',t.program,'year_level',t.year_level,'created_at',t.created_at,'updated_at',t.updated_at,'verification_method',t.verification_method,'verified_by_admin_id',t.verified_by_admin_id,'verified_at',t.verified_at,'row_sha256',encode(sha256(convert_to(to_jsonb(t)::text,'UTF8')),'hex')) order by to_jsonb(t)->>'id',to_jsonb(t)->>'student_id'),'[]') as records from public.student_term_enrollments t where t.academic_term_id=2
union all
select 'public.student_organization_terms' as relation,count(*) as row_count,coalesce(jsonb_agg(jsonb_build_object('id',t.id,'student_id',t.student_id,'organization_id',t.organization_id,'academic_term_id',t.academic_term_id,'status',t.status,'source',t.source,'created_at',t.created_at,'updated_at',t.updated_at,'removed_at',t.removed_at,'removal_reason',t.removal_reason,'row_sha256',encode(sha256(convert_to(to_jsonb(t)::text,'UTF8')),'hex')) order by to_jsonb(t)->>'id',to_jsonb(t)->>'student_id'),'[]') as records from public.student_organization_terms t where t.academic_term_id=2
union all
select 'public.audit_logs' as relation,count(*) as row_count,coalesce(jsonb_agg(jsonb_build_object('id',t.id,'event_type',t.event_type,'event_category',t.event_category,'entity_type',t.entity_type,'entity_id',t.entity_id,'election_id',t.election_id,'organization_id',t.organization_id,'status',t.status,'event_origin',t.event_origin,'created_at',t.created_at,'metadata_keys',(select coalesce(jsonb_agg(k),'[]') from jsonb_object_keys(t.metadata) k),'row_sha256',encode(sha256(convert_to(to_jsonb(t)::text,'UTF8')),'hex')) order by t.id),'[]') as records
from public.audit_logs t where (t.entity_type in ('academic_term','academic_terms') and t.entity_id='2') or t.election_id in(select id from target_elections) or (t.metadata @? '$.**.academic_term_id ? (@ == 2 || @ == "2")' or t.metadata @? '$.**.term_id ? (@ == 2 || @ == "2")' or t.metadata @? '$.**.target_term_id ? (@ == 2 || @ == "2")' or t.metadata @? '$.**.source_term_id ? (@ == 2 || @ == "2")' or t.metadata @? '$.**.previous_academic_term_id ? (@ == 2 || @ == "2")' or t.metadata @? '$.**.new_term_id ? (@ == 2 || @ == "2")' or t.metadata @? '$.**.academic_term.id ? (@ == 2 || @ == "2")' or t.metadata @? '$.**.source_term.id ? (@ == 2 || @ == "2")' or t.metadata @? '$.**.target_term.id ? (@ == 2 || @ == "2")' or (t.metadata::text like '%2nd Semester%' and t.metadata::text like '%2026-2027%'))
union all
select 'public.student_notifications',count(*),coalesce(jsonb_agg(jsonb_build_object('id',t.id,'student_id',t.student_id,'type',t.type,'created_at',t.created_at,'is_read',t.is_read,'metadata_keys',(select coalesce(jsonb_agg(k),'[]') from jsonb_object_keys(t.metadata) k),'row_sha256',encode(sha256(convert_to(to_jsonb(t)::text,'UTF8')),'hex')) order by t.id),'[]')
from public.student_notifications t where (t.metadata @? '$.**.academic_term_id ? (@ == 2 || @ == "2")' or t.metadata @? '$.**.term_id ? (@ == 2 || @ == "2")' or t.metadata @? '$.**.target_term_id ? (@ == 2 || @ == "2")' or t.metadata @? '$.**.source_term_id ? (@ == 2 || @ == "2")' or t.metadata @? '$.**.previous_academic_term_id ? (@ == 2 || @ == "2")' or t.metadata @? '$.**.new_term_id ? (@ == 2 || @ == "2")' or t.metadata @? '$.**.academic_term.id ? (@ == 2 || @ == "2")' or t.metadata @? '$.**.source_term.id ? (@ == 2 || @ == "2")' or t.metadata @? '$.**.target_term.id ? (@ == 2 || @ == "2")' or (t.metadata::text like '%2nd Semester%' and t.metadata::text like '%2026-2027%')) or (t.metadata->>'election_id') in(select id::text from target_elections)
union all
select 'protected_summary' as relation,1 as row_count,jsonb_build_object(
 'active_term',(select to_jsonb(t) from public.academic_terms t where id=1),
 'accounts',(select count(*) from public.students),'organizations',(select count(*) from public.organizations),
 'blocks',(select count(*) from public.blocks),'all_ballots',(select count(*) from public.vote_ballots),'all_votes',(select count(*) from public.votes),
 'shared_structural_memberships',(select count(*) from public.student_organizations),
 'same_year_officers_outside_term2',(select coalesce(jsonb_agg(id order by id),'[]') from public.officers where academic_term_id is distinct from 2 and leadership_academic_year='2026-2027'),
 'year_only_new_roster',(select coalesce(jsonb_agg(id order by id),'[]') from public.officer_new_roster where election_id is null and leadership_academic_year='2026-2027'),
 'year_only_releases',(select coalesce(jsonb_agg(id order by id),'[]') from public.officer_leadership_releases where academic_term_id is null and leadership_academic_year='2026-2027')
) as records loop
    if actual.relation='protected_summary' then continue; end if;
    select coalesce(jsonb_agg(k order by k collate "C"),'[]') into row_keys from (
      select coalesce(r->>'id',r->>'ballot_id',(r->>'election_id')||':'||(r->>'student_id')) as k
      from jsonb_array_elements(actual.records) r
    ) identifiers;
    if actual.row_count<>(reviewed->actual.relation->>'count')::bigint
      or row_keys is distinct from reviewed->actual.relation->'keys' then
      raise exception using errcode='40001',message='Record count or explicit identity scope changed: '||actual.relation;
    end if;
  end loop;
  if md5(pg_get_functiondef(to_regprocedure('private.kandid_guard_anchor_exclusion_register()'))) is distinct from '832839275c9c1969aeacb6897f182d4b' then
    raise exception using errcode='55000',message='Required preservation function changed or is missing.';
  end if;
  if md5(pg_get_functiondef(to_regprocedure('private.kandid_guard_excluded_ballot_votes()'))) is distinct from '2b787f0b3a1ee12f79c0ec7f5b30a531' then
    raise exception using errcode='55000',message='Required preservation function changed or is missing.';
  end if;
  if md5(pg_get_functiondef(to_regprocedure('private.kandid_guard_excluded_ballot()'))) is distinct from '7b488754db5bef1e2f17ca31f06c2764' then
    raise exception using errcode='55000',message='Required preservation function changed or is missing.';
  end if;
  if (select count(*) from pg_trigger where tgenabled='O' and not tgisinternal and (
      (tgrelid='public.vote_ballots'::regclass and tgname='kandid_preserve_excluded_ballot') or
      (tgrelid='public.votes'::regclass and tgname='kandid_preserve_excluded_ballot_votes') or
      (tgrelid='private.ballot_anchor_exclusions'::regclass and tgname in('kandid_preserve_anchor_exclusion_register','kandid_preserve_anchor_exclusion_register_truncate'))))<>4 then
    raise exception using errcode='55000',message='Required preservation triggers changed or are disabled.';
  end if;
  if exists(select 1 from private.ballot_anchor_exclusions where ballot_id='3c5a6c0f-5c69-49d1-bd66-ee4f97383cc1') then
    raise exception using errcode='55000',message='NO_GO: immutable preservation exclusion protects target ballot, vote, receipt and parent election/term. No cleanup is authorized.';
  end if;
  -- Even removal of evidence outside this script cannot arm a deletion.
  raise exception using errcode='55000',message='NO_GO: unresolved classification and preservation review; no deletion scope is approved.';
end;
$review$;
rollback;
